// === Tab: mySketch ===
let num = 500;  // Reduced number of particles
let noiseScale = 500, noiseStrength = 1;
let particles = [];
let trailLength = 50;  // Increase the trail length

function setup() {
  createCanvas(windowWidth, windowHeight);
  noStroke();

  for (let i = 0; i < num; i++) {
    let loc = createVector(random(width * 1.2), random(height), 2);
    let angle = 0; // any value to initialize
    let dir = createVector(cos(angle), sin(angle));
    let speed = random(0.5, 2);
    particles.push(new Particle(loc, dir, speed));
  }
}

function draw() {
  fill(0, 10);
  noStroke();
  rect(0, 0, width, height);

  for (let particle of particles) {
    particle.run();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

class Particle {
  constructor(_loc, _dir, _speed) {
    this.loc = _loc;
    this.dir = _dir;
    this.speed = _speed;
    this.acc = createVector();
    this.vel = createVector();
    this.maxSpeed = 2;
    this.maxForce = 0.1;
    this.trail = [];
  }

  run() {
    this.move();
    this.update();
    this.display();
  }

  move() {
    var angle = noise(this.loc.x / noiseScale, this.loc.y / noiseScale, frameCount / noiseScale) * TWO_PI * noiseStrength;
    this.dir.x = cos(angle);
    this.dir.y = sin(angle);
    let vel = this.dir.copy();
    vel.mult(this.speed);
    this.loc.add(vel);
  }

  update() {
    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed);
    this.loc.add(this.vel);
    this.acc.mult(0);
    this.edges();

    // Add current position to the trail
    this.trail.push(this.loc.copy());
    if (this.trail.length > trailLength) {
      this.trail.shift();  // Remove the oldest position if the trail exceeds the length
    }
  }

  edges() {
    if (this.loc.x < 0) this.loc.x = width;
    if (this.loc.y < 0) this.loc.y = height;
    if (this.loc.x > width) this.loc.x = 0;
    if (this.loc.y > height) this.loc.y = 0;
  }

  display() {
    noFill();
    stroke(255, 255, 255, 100);
    beginShape();
    for (let pos of this.trail) {
      vertex(pos.x, pos.y);
    }
    endShape();
  }
}

